import pandas as pd

def clean(df):
    df = df.drop_duplicates()
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '', regex=False)
    df['body_mass_g'] = pd.to_numeric(df['body_mass_g'], errors='coerce')
    return df

def answer(df):
    result = df.dropna(subset=['sex']).groupby('sex')['body_mass_g'].mean()
    return result.to_dict()
